package ge.opensoft.openservice;
import static ge.opensoft.openservice.Values.*;
import static ge.opensoft.openservice.WorkflowSupport.*;
import static org.junit.jupiter.api.Assertions.*;
import java.util.*;
final class AssistantEvaluationsAcceptance {
 static final String API="/api/openservice/ai-evaluations";
 static String article(WorkflowSupport h)throws Exception{try(var db=h.store.open()){String actor=PlatformFoundationTest.bind(db);String id=KnowledgeSearchAcceptance.article(db,actor,"Evaluation source","Use the approved request form <script>untrusted</script>");db.connection.commit();return id;}}
 static Map<String,Object> dataset(String article){return map("name","Service assistance","version","v1","cohort","held_out","provenance","Cases declared before tuning; synthetic acceptance fixture","latency_budget_ms",30000,"minimum_pass_percent",100,"cases",List.of(map("article_id",article,"question","What should I do?","expected_answer","WITHHELD expected answer <script>not instructions</script>")));}
 static Map<String,Object> post(WorkflowSupport h,String path,Object body,int status)throws Exception{var response=h.json("POST",path,body,auth("admin"));assertEquals(status,response.statusCode(),html(response));return object(parsed(response).get("result"));}
 static String create(WorkflowSupport h,Object body)throws Exception{return post(h,API,body,201).get("suite_id").toString();}
 static Map<String,Object> command(String operation,String run){return map("operation",operation,"run_id",run);}
 static Map<String,Object> preview(WorkflowSupport h,String path,String run,int index)throws Exception{return object(post(h,path,map("operation","preview","run_id",run,"case",index),200).get("preview"));}
 static Map<String,Object> ask(String run,int index,Object token){return map("operation","ask","run_id",run,"case",index,"preview_token",token,"allow_external",true);}
 static Map<String,Object> grade(String run,int index){return map("operation","grade","run_id",run,"case",index,"acceptable",true,"grounded",true,"correction_needed",false,"rationale","Matches the published source and expected outcome");}
 static Map<String,Object> firstRun(Map<String,Object> page){return objects(page.get("runs")).getFirst();}
 static void run(WorkflowSupport h)throws Exception{
  String article=article(h);try(var provider=new RecordQuestionsAcceptance.Provider(h.store,h.environment)){provider.settings.put("AI_KNOWLEDGE_ENABLED","true");String suite=create(h,dataset(article)),path=API+"/"+suite,run=id();var started=post(h,path,command("start",run),200);assertEquals("held_out",firstRun(started).get("cohort"));assertFalse(firstRun(started).containsKey("proof"));assertEquals(KnowledgeQuestions.PROMPT_VERSION,firstRun(started).get("prompt_version"));assertEquals(started.get("dataset_hash"),firstRun(started).get("dataset_hash"));post(h,path,command("start",run),200);assertEquals(0,provider.calls.get());var preview=preview(h,path,run,0);assertFalse(JSON.writeValueAsString(preview).contains("WITHHELD"));var answered=post(h,path,ask(run,0,preview.get("preview_token")),200);var result=objects(firstRun(answered).get("results")).getFirst();assertEquals(provider.answer.get(),result.get("answer"));assertNull(result.get("error"));assertTrue(((Number)result.get("latency_ms")).longValue()>=0);assertFalse(provider.captured.get().contains("WITHHELD"));assertTrue(provider.captured.get().contains("Use the approved request form"));assertFalse(provider.captured.get().contains("synthetic-question-token"));var payload=object(JSON.readValue(provider.captured.get(),Object.class));assertEquals(800,payload.get("max_completion_tokens"));assertEquals(false,payload.get("store"));assertFalse(payload.containsKey("tools"));post(h,path,ask(run,0,"replay returns retained result"),200);assertEquals(1,provider.calls.get());post(h,path,grade(run,0),200);var finished=post(h,path,command("finish",run),200);var summary=object(firstRun(finished).get("summary"));assertEquals(1,summary.get("passed"));assertEquals(100.0,((Number)summary.get("pass_percent")).doubleValue());assertEquals(true,summary.get("meets_declared_budget"));assertEquals(0,summary.get("provider_failures"));assertEquals(1,summary.get("human_graded"));assertNull(summary.get("billed_tokens"));assertNull(summary.get("billed_cost"));post(h,path,ask(run,0,"retained completed result"),200);assertEquals(1,provider.calls.get());assertEquals(400,h.json("POST",path,grade(run,0),auth("admin")).statusCode());assertEquals(400,h.json("POST",path,command("finish",run),auth("admin")).statusCode());
   new Store(h.environment);var retained=object(parsed(h.get(path,auth("admin"))).get("result"));assertEquals(firstRun(finished),firstRun(retained));String next=id();var repeated=post(h,path,command("start",next),200);assertEquals("regression",objects(repeated.get("runs")).getLast().get("cohort"));post(h,path,command("cancel",next),200);assertEquals(400,h.json("POST",path,map("operation","preview","run_id",next,"case",0),auth("admin")).statusCode());assertEquals(400,h.json("POST",path,ask(next,0,"no"),auth("admin")).statusCode());assertEquals(1,provider.calls.get());try(var db=h.store.open()){var row=db.one("SELECT * FROM os_ai_evaluation WHERE suite_id=?",suite);assertFalse(row.get("envelope").toString().contains("WITHHELD"));assertFalse(row.get("envelope").toString().contains(provider.answer.get()));assertTrue(JSON.writeValueAsString(Outbox.decrypt(h.store.secret,row.get("envelope").toString())).contains("WITHHELD"));String audit=JSON.writeValueAsString(db.all("SELECT * FROM os_security_event WHERE action LIKE 'ai.evaluation_%'"));assertFalse(audit.contains("WITHHELD"));assertFalse(audit.contains("What should I do?"));assertFalse(audit.contains(provider.answer.get()));}
   post(h,path,map("operation","delete","confirm",true),200);assertEquals(404,h.get(path,auth("admin")).statusCode());
  }
 }
 static void boundaries(WorkflowSupport h)throws Exception{
  h.account("EvaluationOther","admin");h.account("EvaluationAgent","agent");String article=article(h),suite=create(h,dataset(article)),path=API+"/"+suite,run=id();assertEquals(401,h.get(API,null).statusCode());assertEquals(403,h.get(API,auth("EvaluationAgent")).statusCode());assertEquals(404,h.get(path,auth("EvaluationOther")).statusCode());assertEquals(404,h.json("POST",path,map("operation","delete","confirm",true),auth("EvaluationOther")).statusCode());assertEquals(400,h.get(API+"?x=y",auth("admin")).statusCode());assertEquals(405,h.json("PUT",path,map(),auth("admin")).statusCode());assertEquals(403,h.form("/admin/ai-evaluations",dataset(article),auth("admin")).statusCode());assertEquals(200,h.get(API,auth("admin")).statusCode());assertEquals(200,h.get("/admin/ai-evaluations",auth("admin")).statusCode());assertEquals(200,h.get("/admin/ai-evaluations/"+suite,auth("admin")).statusCode());
  for(var field:List.of(Map.entry("name",""),Map.entry("version","x".repeat(81)),Map.entry("cohort","unknown"),Map.entry("provenance",""),Map.entry("latency_budget_ms",0),Map.entry("latency_budget_ms",30001),Map.entry("latency_budget_ms","1"),Map.entry("minimum_pass_percent",-1),Map.entry("minimum_pass_percent",101),Map.entry("cases",map()),Map.entry("cases",List.of()),Map.entry("cases",List.of("scalar")),Map.entry("cases",Arrays.asList((Object)null)),Map.entry("cases",List.of(map())),Map.entry("cases",Collections.nCopies(11,objects(dataset(article).get("cases")).getFirst())),Map.entry("extra",true))){var body=dataset(article);body.put(field.getKey(),field.getValue());assertEquals(400,h.json("POST",API,body,auth("admin")).statusCode(),field.getKey());}
  var bad=dataset(article);bad.remove("name");assertEquals(400,h.json("POST",API,bad,auth("admin")).statusCode());bad=dataset(article);bad.put("cases",List.of(map("article_id",article,"question","","expected_answer","x")));assertEquals(400,h.json("POST",API,bad,auth("admin")).statusCode());bad=dataset(article);bad.put("cases",List.of(map("article_id",id(),"question","x","expected_answer","x")));assertEquals(404,h.json("POST",API,bad,auth("admin")).statusCode());
  for(var body:List.of(map(),map("operation","unknown"),map("operation","start","run_id","bad"),map("operation","start","run_id",run,"extra",true),map("operation","delete","confirm",false),map("operation","delete","confirm",true,"extra",true)))assertEquals(400,h.json("POST",path,body,auth("admin")).statusCode());assertEquals(404,h.json("POST",path,command("finish",run),auth("admin")).statusCode());post(h,path,command("start",run),200);
  for(var body:List.of(map("operation","finish","run_id",run,"extra",true),command("finish",run),map("operation","preview","run_id",run,"case",-1),map("operation","preview","run_id",run,"case",1),map("operation","preview","run_id",run,"case","0"),map("operation","preview","run_id",run,"case",0,"extra",true),map("operation","ask","run_id",run,"case",0,"preview_token","bad"),map("operation","ask","run_id",run,"case",0,"preview_token","bad","allow_external",false),grade(run,0),map("operation","grade","run_id",run,"case",0)))assertEquals(400,h.json("POST",path,body,auth("admin")).statusCode());
  var form=new LinkedHashMap<String,Object>(dataset(article));form.put("cases","{invalid");assertEquals(400,h.protectedForm("/admin/ai-evaluations",form,auth("admin")).statusCode());form.put("cases",JSON.writeValueAsString(dataset(article).get("cases")));assertEquals(302,h.protectedForm("/admin/ai-evaluations",form,auth("admin")).statusCode());assertEquals(400,h.protectedForm("/admin/ai-evaluations/"+suite,map("operation","delete","confirm","false"),auth("admin")).statusCode());assertEquals(302,h.protectedForm("/admin/ai-evaluations/"+suite,map("operation","delete","confirm","true"),auth("admin")).statusCode());
 }
 static void changes(WorkflowSupport h)throws Exception{
  String article=article(h);try(var provider=new RecordQuestionsAcceptance.Provider(h.store,h.environment)){provider.settings.put("AI_KNOWLEDGE_ENABLED","true");String suite=create(h,dataset(article)),path=API+"/"+suite,run=id(),other=id();post(h,path,command("start",run),200);post(h,path,command("start",other),200);var pre=preview(h,path,run,0);assertEquals(409,h.json("POST",path,ask(other,0,pre.get("preview_token")),auth("admin")).statusCode());assertEquals(400,h.json("POST",path,ask(run,0,"bad"),auth("admin")).statusCode());var expired=Outbox.decrypt("ai-consent-v1:"+h.store.secret,pre.get("preview_token").toString());expired.put("expires_at",0);assertEquals(409,h.json("POST",path,ask(run,0,Outbox.encrypt("ai-consent-v1:"+h.store.secret,JSON.writeValueAsString(expired))),auth("admin")).statusCode());
   for(var field:List.of(Map.entry("AI_ENABLED","false"),Map.entry("AI_KNOWLEDGE_ENABLED","false"),Map.entry("AI_MODEL","changed"),Map.entry("AI_CONNECTOR_ALIAS","missing"),Map.entry("CONNECTOR_ALLOWED_ORIGINS",""))){Object old=provider.settings.put(field.getKey(),field.getValue());assertEquals(409,h.json("POST",path,ask(run,0,pre.get("preview_token")),auth("admin")).statusCode());provider.settings.put(field.getKey(),old);}assertEquals(0,provider.calls.get());
   try(var db=h.store.open()){db.update("UPDATE os_user SET auth_revision=auth_revision+1 WHERE name='admin'");db.connection.commit();}assertEquals(409,h.json("POST",path,ask(run,0,pre.get("preview_token")),auth("admin")).statusCode());String fresh=id();post(h,path,command("start",fresh),200);var freshPre=preview(h,path,fresh,0);post(h,path,ask(fresh,0,freshPre.get("preview_token")),200);assertEquals(1,provider.calls.get());
   try(var db=h.store.open()){String actor=PlatformFoundationTest.bind(db);Service.update(db,"kb_knowledge",Service.record(db,"kb_knowledge",article),map("text","Changed published answer"),"admin","admin",null);PublishedKnowledge.publish(db,actor,article);db.connection.commit();}assertEquals(409,h.get(path,auth("admin")).statusCode());assertEquals(409,h.json("POST",path,grade(fresh,0),auth("admin")).statusCode());post(h,path,map("operation","delete","confirm",true),200);
   suite=create(h,dataset(article));path=API+"/"+suite;try(var db=h.store.open()){String actor=PlatformFoundationTest.bind(db);PublishedKnowledge.retire(db,actor,article);db.connection.commit();}assertEquals(404,h.get(path,auth("admin")).statusCode());post(h,path,map("operation","delete","confirm",true),200);
  }
 }
 static void outcomes(WorkflowSupport h)throws Exception{
  String article=article(h);try(var provider=new RecordQuestionsAcceptance.Provider(h.store,h.environment)){provider.settings.put("AI_KNOWLEDGE_ENABLED","true");var body=dataset(article);body.put("cohort","development");body.put("cases",Collections.nCopies(6,objects(body.get("cases")).getFirst()));body.put("minimum_pass_percent",17);String suite=create(h,body),path=API+"/"+suite,run=id();var page=post(h,path,command("start",run),200);assertEquals("development",firstRun(page).get("cohort"));
   for(int n=0;n<6;n++){var pre=preview(h,path,run,n);if(n==5)provider.status.set(503);page=post(h,path,ask(run,n,pre.get("preview_token")),200);if(n==0){assertEquals(409,h.json("POST",path,ask(run,1,pre.get("preview_token")),auth("admin")).statusCode());assertEquals(400,h.json("POST",path,map("operation","preview","run_id",run,"case",0),auth("admin")).statusCode());}if(n<5){var grade=grade(run,n);if(n==0){var invalid=new LinkedHashMap<>(grade);invalid.put("acceptable","yes");assertEquals(400,h.json("POST",path,invalid,auth("admin")).statusCode());invalid.put("acceptable",true);invalid.put("rationale","");assertEquals(400,h.json("POST",path,invalid,auth("admin")).statusCode());}if(n==1)grade.put("acceptable",false);if(n==2)grade.put("grounded",false);if(n==3)grade.put("correction_needed",true);post(h,path,grade,200);}}
   assertEquals(400,h.json("POST",path,grade(run,5),auth("admin")).statusCode());assertEquals(6,provider.calls.get());try(var db=h.store.open()){var row=db.one("SELECT * FROM os_ai_evaluation WHERE suite_id=?",suite);var data=Outbox.decrypt(h.store.secret,row.get("envelope").toString());var results=objects(firstRun(data).get("results"));for(var result:results)result.put("latency_ms",1);results.get(4).put("latency_ms",30001);db.update("UPDATE os_ai_evaluation SET envelope=? WHERE suite_id=?",Outbox.encrypt(h.store.secret,JSON.writeValueAsString(data)),suite);db.connection.commit();}page=post(h,path,command("finish",run),200);var summary=object(firstRun(page).get("summary"));assertEquals(1,summary.get("passed"));assertEquals(16.67,((Number)summary.get("pass_percent")).doubleValue());assertEquals(false,summary.get("meets_declared_budget"));assertEquals(1,summary.get("provider_failures"));assertEquals(5,summary.get("human_graded"));assertEquals(1,summary.get("corrections"));assertEquals(5001.0,((Number)summary.get("mean_latency_ms")).doubleValue());assertEquals(30001,((Number)summary.get("max_latency_ms")).intValue());
   String second=id();post(h,path,command("start",second),200);provider.status.set(200);for(int n=0;n<6;n++){var pre=preview(h,path,second,n);post(h,path,ask(second,n,pre.get("preview_token")),200);}assertEquals(400,h.json("POST",path,command("finish",second),auth("admin")).statusCode());post(h,path,command("cancel",second),200);assertEquals(400,h.json("POST",path,grade(second,0),auth("admin")).statusCode());assertEquals(12,provider.calls.get());
  }
 }
 static void concurrencyAndBudget(WorkflowSupport h)throws Exception{
  String article=article(h);try(var provider=new RecordQuestionsAcceptance.Provider(h.store,h.environment)){provider.settings.put("AI_KNOWLEDGE_ENABLED","true");String suite=create(h,dataset(article)),path=API+"/"+suite,run=id();post(h,path,command("start",run),200);var pre=preview(h,path,run,0);var ask=ask(run,0,pre.get("preview_token"));try(var pool=java.util.concurrent.Executors.newFixedThreadPool(2)){var first=pool.submit(()->post(h,path,ask,200));var second=pool.submit(()->post(h,path,ask,200));assertEquals(firstRun(first.get()),firstRun(second.get()));}assertEquals(1,provider.calls.get());
   try(var db=h.store.open()){String actor=PlatformFoundationTest.bind(db);for(int i=1;i<20;i++)SecurityEvents.record(db,actor,actor,"ai.knowledge_attempted",map("fixture","hourly budget"));db.connection.commit();}String next=id();post(h,path,command("start",next),200);var nextPre=preview(h,path,next,0);assertEquals(429,h.json("POST",path,ask(next,0,nextPre.get("preview_token")),auth("admin")).statusCode());assertEquals(1,provider.calls.get());var retained=object(parsed(h.get(path,auth("admin"))).get("result"));assertEquals(false,objects(objects(retained.get("runs")).getLast().get("results")).getFirst().get("attempted"));
   provider.settings.put("AI_KNOWLEDGE_ENABLED","false");String disabled=id();post(h,path,command("start",disabled),200);var disabledPre=preview(h,path,disabled,0);assertEquals(503,h.json("POST",path,ask(disabled,0,disabledPre.get("preview_token")),auth("admin")).statusCode());assertEquals(1,provider.calls.get());
  }
 }
 static void limits(WorkflowSupport h)throws Exception{
  String article=article(h),suite=create(h,dataset(article)),path=API+"/"+suite;for(int i=0;i<20;i++)post(h,path,command("start",id()),200);assertEquals(400,h.json("POST",path,command("start",id()),auth("admin")).statusCode());for(int i=1;i<20;i++)create(h,dataset(article));assertEquals(400,h.json("POST",API,dataset(article),auth("admin")).statusCode());try(var db=h.store.open()){db.update("UPDATE os_ai_evaluation SET owner_id='other'");var row=db.one("SELECT * FROM os_ai_evaluation WHERE suite_id=?",suite);for(int i=20;i<5000;i++)db.update("INSERT INTO os_ai_evaluation(suite_id,owner_id,name,version,cohort,dataset_hash,envelope,created) VALUES(?,'other','synthetic','v1','development',?,?,?)",id(),row.get("dataset_hash"),row.get("envelope"),now());db.connection.commit();}assertEquals(400,h.json("POST",API,dataset(article),auth("admin")).statusCode());
 }
}
